SELECT COUNT(DISTINCT f.productclass) FROM (
    SELECT f.productclass, COUNT(*) as cnt 
    FROM funds f JOIN risk_metrics r ON f.tickersym = r.investmentref 
    WHERE f.productclass IS NOT NULL AND r.alpha3y IS NOT NULL AND f.turnoverratio IS NOT NULL 
    GROUP BY f.productclass HAVING COUNT(*) >= 20
) sub;

SELECT COUNT(*) FROM (
    SELECT f.productclass, COUNT(*) as cnt 
    FROM funds f JOIN risk_metrics r ON f.tickersym = r.investmentref 
    WHERE f.productclass IS NOT NULL AND r.alpha3y IS NOT NULL AND f.turnoverratio IS NOT NULL 
    GROUP BY f.productclass HAVING COUNT(*) >= 20
) sub;

